    font-variant-numeric: tabular-nums;
  }
}

@layer utilities {
  /* A logged row is marked with a short colour highlight (no movement, so it also runs under reduced motion). */
  .row-new {
    animation: row-new 900ms cubic-bezier(0.2, 0.7, 0.2, 1) 1;
  }

  @keyframes row-new {
    from {
      background-color: rgb(227 176 75 / 0.28); /* barley at 28% */
    }
    to {
      background-color: transparent;
    }
  }
}

/* Movement only when the visitor allows it. Colour and opacity changes stay. */
@media (prefers-reduced-motion: no-preference) {
  .key:active {
    transform: scale(0.97);
    transition: transform 120ms cubic-bezier(0.2, 0.7, 0.2, 1);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
